// Generates src/core/world/valley_layout.ts from docs/tasks/003-layout/layout.json (003-layout, "For Viktor" 1).
// The JSON is the source of truth; the generated file is never edited by hand.
// Usage: node scripts/gen_valley_layout.mjs           (write the file)
//        node scripts/gen_valley_layout.mjs --check   (exit 1 if the file is out of date)
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(fileURLToPath(new URL('..', import.meta.url)));
const SRC = resolve(root, 'docs/tasks/003-layout/layout.json');
const OUT = resolve(root, 'src/core/world/valley_layout.ts');

// The prototype's river beds (docs/tasks/003-layout/check.ts) were laid as round hollows of this size.
// The JSON's prototype_terrain must contain exactly these hollows; valley.ts lays the real ones at RIVER_BED.
const PROTOTYPE_RIVER = { radius: 20, height: -14, step: 12 };

const camel = (s) => s.replace(/_([a-z])/g, (_, c) => c.toUpperCase());
const pt = (x, z) => ({ x, z });

/** Same rule as check.ts chain(): round hollows every `step` metres along each line. */
function chain(line, radius, height, step) {
  const out = [];
  for (let i = 0; i + 1 < line.length; i++) {
    const [ax, az] = line[i];
    const [bx, bz] = line[i + 1];
    const n = Math.max(1, Math.round(Math.hypot(bx - ax, bz - az) / step));
    for (let k = 0; k < n; k++) {
      out.push({ x: Math.round(ax + ((bx - ax) * k) / n), z: Math.round(az + ((bz - az) * k) / n), radius, height });
    }
  }
  const [lx, lz] = line[line.length - 1];
  out.push({ x: lx, z: lz, radius, height });
  return out;
}

const keyOf = (f) => `${f.x},${f.z},${f.radius},${f.height}`;

function verifyPrototypeRivers(layout) {
  const rivers = [
    ...chain(layout.river_in.map((p) => [p.x ?? p[0], p.z ?? p[1]]), PROTOTYPE_RIVER.radius, PROTOTYPE_RIVER.height, PROTOTYPE_RIVER.step),
    ...chain(layout.river_out.map((p) => [p.x ?? p[0], p.z ?? p[1]]), PROTOTYPE_RIVER.radius, PROTOTYPE_RIVER.height, PROTOTYPE_RIVER.step),
  ];
  const expected = rivers.map(keyOf).sort();
  const actual = layout.prototype_terrain.features
    .filter((f) => f.radius === PROTOTYPE_RIVER.radius && f.height === PROTOTYPE_RIVER.height)
    .map(keyOf)
    .sort();
  if (expected.length !== actual.length || expected.some((k, i) => k !== actual[i])) {
    throw new Error(`prototype river beds in layout.json (${actual.length}) do not match the river lines (${expected.length})`);
  }
}

const toPoint = (p) => (Array.isArray(p) ? pt(p[0], p[1]) : pt(p.x, p.z));
const lit = (v) => JSON.stringify(v, null, 2).replace(/"([A-Za-z_][A-Za-z0-9_]*)":/g, '$1:');

function render(layout) {
  verifyPrototypeRivers(layout);
  const placeEntries = Object.entries(layout.places);
  const places = Object.fromEntries(placeEntries.map(([k, v]) => [camel(k), pt(v.x, v.z)]));
  const placeStops = placeEntries
    .filter(([k]) => k !== 'lake' && k !== 'castle')
    .map(([k, v]) => ({ name: k, kind: 'place', x: v.x, z: v.z }));
  const signposts = layout.signposts.map((s) => ({ name: s.name, kind: 'signpost', x: s.x, z: s.z }));
  const minor = layout.stops.map((s) => ({ name: s.name, kind: s.kind, x: s.x, z: s.z, note: s.note }));
  const stops = [...placeStops, ...signposts, ...minor];
  const features = layout.prototype_terrain.features.filter(
    (f) => !(f.radius === PROTOTYPE_RIVER.radius && f.height === PROTOTYPE_RIVER.height),
  );
  const roads = Object.fromEntries(Object.entries(layout.roads).map(([k, line]) => [k, line.map(toPoint)]));

  return `// GENERATED by scripts/gen_valley_layout.mjs from docs/tasks/003-layout/layout.json. Do not edit by hand.
// Change the JSON, run \`node scripts/gen_valley_layout.mjs\`; \`--check\` fails the gate if this file is stale.
// Metres. x is east, z is south, north is -z.

export interface LayoutPoint {
  readonly x: number;
  readonly z: number;
}

export interface LayoutStop extends LayoutPoint {
  readonly name: string;
  readonly kind: string;
  readonly note?: string;
}

export interface LayoutFeature extends LayoutPoint {
  readonly radius: number;
  readonly height: number;
}

export const VALLEY_BASE_HEIGHT = ${layout.prototype_terrain.baseHeight};

export const VALLEY_LAYERS: readonly { readonly wavelength: number; readonly amplitude: number }[] = ${lit(layout.prototype_terrain.layers)};

/** Hills, the lake basin, the east ridge, the rim and the screens. River beds are laid by valley.ts. */
export const VALLEY_TERRAIN_FEATURES: readonly LayoutFeature[] = ${lit(features)};

/** The named places (003-layout, "The places"). */
export const VALLEY_PLACES = ${lit(places)} as const;

export const VALLEY_CROSSINGS: readonly { readonly name: string; readonly x: number; readonly z: number }[] = ${lit(layout.crossings)};

export const VALLEY_ROADS: Readonly<Record<string, readonly LayoutPoint[]>> = ${lit(roads)};

/** The river in: over the west rim, past the Mill, into the lake's west side. */
export const VALLEY_RIVER_IN: readonly LayoutPoint[] = ${lit(layout.river_in.map(toPoint))};

/** The river out: the lake's east side, the ford, the south-east gorge. */
export const VALLEY_RIVER_OUT: readonly LayoutPoint[] = ${lit(layout.river_out.map(toPoint))};

export const VALLEY_EAST_RIDGE: readonly LayoutPoint[] = ${lit(layout.east_ridge.map(toPoint))};

export const VALLEY_SIGNPOSTS: readonly LayoutStop[] = ${lit(signposts)};

/** Everything placed that is worth stopping for: the places (not the lake or the castle), the signposts, and the 28 stops. */
export const VALLEY_STOPS: readonly LayoutStop[] = ${lit(stops)};
`;
}

function main() {
  const layout = JSON.parse(readFileSync(SRC, 'utf8'));
  const text = render(layout);
  if (process.argv.includes('--check')) {
    let current = '';
    try {
      current = readFileSync(OUT, 'utf8');
    } catch {
      current = '';
    }
    if (current !== text) {
      console.error(`FAIL: ${OUT} is out of date with ${SRC}. Run: node scripts/gen_valley_layout.mjs`);
      process.exit(1);
    }
    console.log('PASS: valley_layout.ts matches layout.json.');
    return;
  }
  writeFileSync(OUT, text);
  console.log(`wrote ${OUT}`);
}

main();
